// Construye la solicitud de envío a WhatsApp Cloud API (operación channel.send)
const r = $json;
const s = r.settings || {};
const inp = r.input || {};
const m = inp.message || {};
const fail = (code, message) => ({ json: { skip: true, status: 'PERMANENT_ERROR', error: { code, message } } });
if (!s.graph_api_version || !s.phone_number_id) return fail('VALIDATION', 'faltan settings.graph_api_version o settings.phone_number_id');
if (!inp.to) return fail('VALIDATION', 'falta input.to');
const body = { messaging_product: 'whatsapp', recipient_type: 'individual', to: String(inp.to) };
const t = m.type;
if (t === 'text') { body.type = 'text'; body.text = { body: m.text, preview_url: m.preview_url === true }; }
else if (['image', 'video', 'audio', 'document', 'sticker'].includes(t)) {
  if (!m.media_url) return fail('VALIDATION', 'mensaje ' + t + ' sin media_url');
  body.type = t; body[t] = { link: m.media_url };
  if (m.caption && ['image', 'video', 'document'].includes(t)) body[t].caption = m.caption;
  if (m.filename && t === 'document') body[t].filename = m.filename;
} else if (t === 'template') {
  if (!m.template?.name || !m.template?.language) return fail('VALIDATION', 'plantilla sin name o language');
  body.type = 'template'; body.template = { name: m.template.name, language: { code: m.template.language }, components: m.template.components || [] };
} else if (t === 'interactive') {
  if (!m.interactive) return fail('VALIDATION', 'mensaje interactive sin objeto interactive');
  body.type = 'interactive'; body.interactive = m.interactive;
} else if (t === 'reaction') {
  body.type = 'reaction'; body.reaction = { message_id: m.reply_to_message_id, emoji: m.emoji };
} else return fail('VALIDATION', 'tipo de mensaje no soportado: ' + t);
if (inp.reply_to_message_id && t !== 'reaction') body.context = { message_id: inp.reply_to_message_id };
return { json: { skip: false, url: 'https://graph.facebook.com/' + s.graph_api_version + '/' + s.phone_number_id + '/messages', body, timeout_ms: s.timeout_ms || 10000 } };

// Normaliza la respuesta de envío de WhatsApp al contrato channel.send
const res = $json;
const code = res.statusCode;
const body = res.body || {};
if (code >= 200 && code < 300 && body.messages && body.messages[0]) {
  return { json: { status: 'OK', data: { provider_message_id: body.messages[0].id, recipient: body.contacts?.[0]?.wa_id || null, accepted_at: new Date().toISOString(), message_status: body.messages[0].message_status || 'accepted' }, error: null } };
}
const e = body.error || {};
const c = Number(e.code);
let status = 'PERMANENT_ERROR', err = 'HTTP_' + code;
if (c === 131047) err = 'WINDOW_CLOSED';
else if (c === 131026) err = 'UNDELIVERABLE';
else if (c >= 132000 && c < 133000) err = 'TEMPLATE_ERROR';
else if ([190, 10, 200].includes(c)) err = 'AUTH_ERROR';
else if ([4, 80007, 130429, 131048, 131056].includes(c)) { status = 'RETRYABLE_ERROR'; err = 'RATE_LIMIT'; }
else if (code === 408 || code === 429 || code >= 500) { status = 'RETRYABLE_ERROR'; }
return { json: { status, data: null, error: { code: err, provider_code: e.code ?? null, message: e.message || e.error_data?.details || ('HTTP ' + code), http_status: code } } };

// Interpreta la respuesta de GET /{media_id} (URL temporal de descarga)
const res = $json;
const b = res.body || {};
if (res.statusCode >= 200 && res.statusCode < 300 && b.url) {
  return { json: { ok: true, url: b.url, mime_type: b.mime_type || null, sha256: b.sha256 || null, file_size: b.file_size || null, media_id: b.id || null } };
}
const retry = res.statusCode === 429 || res.statusCode >= 500;
return { json: { ok: false, status: res.statusCode === 404 ? 'NOT_FOUND' : (retry ? 'RETRYABLE_ERROR' : 'PERMANENT_ERROR'), data: null, error: { code: 'HTTP_' + res.statusCode, message: b.error?.message || 'no se obtuvo la URL del archivo', http_status: res.statusCode } } };

// Entrega el archivo descargado como binario 'data' y sus metadatos
const meta = $('Interpretar metadatos del archivo').item.json;
return { json: { status: 'OK', data: { media_id: meta.media_id, mime_type: meta.mime_type, sha256: meta.sha256, file_size: meta.file_size }, error: null }, binary: $input.item.binary };

// Timeout o error de red después de enviar: no se sabe si el proveedor ejecutó la acción (UNKNOWN)
const msg = $json.error?.message ?? String($json.error ?? 'error de red');
return { json: { status: 'UNKNOWN', data: null, error: { code: /timeout/i.test(msg) ? 'TIMEOUT' : 'NETWORK_ERROR', message: msg } } };

// Timeout o error de red en una operación NO sensible: reintentable
const msg = $json.error?.message ?? String($json.error ?? 'error de red');
return { json: { status: 'RETRYABLE_ERROR', data: null, error: { code: /timeout/i.test(msg) ? 'TIMEOUT' : 'NETWORK_ERROR', message: msg } } };

// Lee el cuerpo crudo y la firma del webhook de WhatsApp Cloud API (la firma se verifica en la base)
const item = $input.first();
let buf;
try { buf = await this.helpers.getBinaryDataBuffer(0, 'data'); } catch (e) { buf = Buffer.from(JSON.stringify(item.json.body || {}), 'utf8'); }
const h = item.json.headers || {};
return [{ json: {
  raw: buf.toString('utf8'),
  signature: h['x-hub-signature-256'] || null,
  body: item.json.body || {}
} }];

// Normaliza el webhook de WhatsApp Cloud API.
// Mensajes → contrato dalia.channel.inbound_message/1.0 hacia el destino configurado (M1.01).
// Estados de entrega, mensajes con firma inválida o sin destino → SYS.03 (inbox).
// Sin mensajes ni estados → un ítem route = 'none' (solo se responde 200).
const chk = $json.chk || {};
const w = $('Leer cuerpo crudo').first().json;
const b = w.body || {};
const iso = (ts) => ts ? new Date(Number(ts) * 1000).toISOString() : null;
const out = [];
const valid = chk.signature_valid === true;
const target = chk.target_workflow_id || null;
for (const entry of (b.entry || [])) {
  for (const change of (entry.changes || [])) {
    const v = change.value || {};
    const account = v.metadata?.phone_number_id || null;
    const names = {};
    for (const c of (v.contacts || [])) names[c.wa_id] = c.profile?.name || null;
    for (const m of (v.messages || [])) {
      const t = m.type;
      let family = 'content', text = null, media = null, interaction = null, location = null, extra = null;
      if (t === 'text') text = m.text?.body ?? null;
      else if (['image', 'audio', 'video', 'document', 'sticker'].includes(t)) {
        const x = m[t] || {};
        media = { media_id: x.id, mime_type: x.mime_type || null, sha256: x.sha256 || null, caption: x.caption || null, filename: x.filename || null, voice: x.voice === true };
        text = x.caption || null;
      } else if (t === 'location') {
        location = { latitude: m.location?.latitude, longitude: m.location?.longitude, name: m.location?.name || null, address: m.location?.address || null };
      } else if (t === 'contacts') { extra = { contacts: m.contacts || [] }; }
      else if (t === 'order') { extra = { order: m.order || null }; }
      else if (t === 'interactive') {
        family = 'interaction';
        const r = m.interactive?.button_reply || m.interactive?.list_reply || m.interactive?.nfm_reply || {};
        interaction = { kind: m.interactive?.type || 'interactive', id: r.id || null, title: r.title || null, description: r.description || null, response_json: r.response_json || null };
      } else if (t === 'button') {
        family = 'interaction';
        interaction = { kind: 'quick_reply', id: m.button?.payload || null, title: m.button?.text || null };
      } else if (t === 'reaction') {
        family = 'interaction';
        interaction = { kind: 'reaction', reply_to_message_id: m.reaction?.message_id || null, emoji: m.reaction?.emoji || null };
      } else if (t === 'system') { family = 'system'; extra = { system: m.system || null }; }
      else { family = 'unsupported'; }
      const msg = {
        contract: 'dalia.channel.inbound_message/1.0',
        channel: 'whatsapp',
        channel_account_ref: account,
        channel_message_id: m.id,
        channel_thread_id: m.from,
        from: { channel_user_id: m.from, display_name: names[m.from] || null },
        sent_at: iso(m.timestamp),
        received_at: new Date().toISOString(),
        family,
        content_type: t || 'unknown',
        text, media, interaction, location, extra,
        context: m.context ? { reply_to_message_id: m.context.id || null, forwarded: m.context.forwarded === true } : null,
        provider_errors: m.errors || null,
        raw: m
      };
      if (valid && target) out.push({ json: Object.assign({ route: 'inbound', target_workflow_id: target }, msg) });
      else out.push({ json: { route: 'callback', source: 'channel.whatsapp', external_event_id: m.id, event_type: 'message.received', signature_valid: valid, payload: msg, envelope: {} } });
    }
    for (const s of (v.statuses || [])) {
      out.push({ json: { route: 'callback', source: 'channel.whatsapp', external_event_id: s.id + ':' + s.status, event_type: 'delivery.status', signature_valid: valid, payload: { provider_message_id: s.id, status: s.status, occurred_at: iso(s.timestamp), recipient: s.recipient_id || null, conversation: s.conversation || null, pricing: s.pricing || null, errors: s.errors || null }, envelope: {} } });
    }
  }
}
if (out.length === 0) out.push({ json: { route: 'none' } });
return out;

